'use strict';
/* Mobile personal-assistant presentation. Fictional briefing, no live curation. */
window.assistantModule=(()=>{
  const deferred=new Set();
  const acknowledged=new Set();
  const notes={};
  const items=[
    {id:'decision',activity:'attention',title:'设计草案整理好了，保存前等你点头',why:'已整理出默认底色、排版和手机列表的约定。确认后才会加入资料，不会替你直接保存。',timing:'今天 · 先确认再执行',source:'design',sourceTitle:'让 Nola 更像 Nola',cta:'审阅并决定',action:'mg-activity:attention'},
    {id:'compare',title:'模型怎么选，先看这三个取舍',why:'速度、资源占用、稳定性分开看。比较方法已整理好，不必再翻完整对话。',timing:'今天 · 有空时看',source:'compare',sourceTitle:'本地模型，怎么选更合适',cta:'看整理结果',action:'ws-detail:compare'}
  ];
  const b=(text,action,cls='text-action')=>`<button class="${cls}" data-action="${action}">${text}</button>`;
  const activity=id=>window.manageModule?.snapshot().activities.find(a=>a.id===id);
  const state=i=>acknowledged.has(i.id)?'已看过':i.activity?(activity(i.activity)?.status||'待确认'):'已整理';
  const resolved=i=>acknowledged.has(i.id)||['已完成','已拒绝'].includes(state(i));
  function card(i){const s=state(i);return `<article class="assistant-matter" style="padding:22px 0;border-bottom:1px solid var(--line)"><div class="meta" style="margin-bottom:8px">${esc(i.timing)} · ${esc(s)}</div><h2 style="font-size:21px;line-height:31px;font-weight:550;letter-spacing:-.4px">${esc(i.title)}</h2><p style="margin-top:10px;font-size:15px;line-height:25px;color:var(--muted)">${esc(i.why)}</p>${notes[i.id]?`<p class="inline-block">你留下的话：${esc(notes[i.id])}</p>`:''}<div class="action-wrap" style="margin-top:14px;margin-bottom:4px">${b(i.cta,i.action,'primary')}${b('稍后看','as-later:'+i.id)}</div><button class="text-action" style="justify-content:flex-start;padding-left:0;white-space:normal;text-align:left;font-size:12px;color:var(--muted);line-height:19px" data-action="chat:${i.source}">${svg('chat')} ${esc(i.sourceTitle)}</button>${b('补充一句','as-reply:'+i.id)}${!i.activity?b('标记已看','as-done:'+i.id):''}</article>`}
  function view(){const today=items.filter(i=>!deferred.has(i.id)&&!resolved(i));const waiting=activity('input');const failure=activity('failure');const complete=items.filter(resolved);const later=items.filter(i=>deferred.has(i.id)&&!resolved(i));const upcoming=typeof plans!=='undefined'?plans.filter(p=>p.on):[];return `<section class="page assistant-home">${mobileBrand()}<header class="page-head"><div><h1>今日</h1><p>今天，先替你理好这些。</p></div>${b('信息','nav:information')}</header><section aria-labelledby="assistant-today"><div class="section-heading" style="margin-top:8px;margin-bottom:0"><h2 id="assistant-today" style="font-size:16px">今日事项</h2><span class="meta">${today.length} 件待看 · 演示</span></div>${today.length?today.map(card).join(''):`<div style="padding:28px 0;border-bottom:1px solid var(--line)"><h2>今天的重点，都看过了。</h2><p class="muted" style="margin-top:8px;font-size:14px">没有新的事项需要处理。你可以继续聊天，或看看稍后留下的内容。</p>${b('去聊聊','nav:conversations')}</div>`}</section><section aria-labelledby="assistant-waits"><div class="section-heading"><h2 id="assistant-waits">还需要你一句话</h2>${b('全部活动','nav:activity')}</div>${waiting&&waiting.status==='待补充'?`<div class="object-row"><div class="object-copy"><h3>阅读摘记，保留哪些内容？</h3><p>整理已暂停，等你给一个范围。不急着替你猜。</p><p class="meta">来自阅读与整理 · 等待补充</p>${b('告诉 Nola','mg-activity:input')}</div></div>`:`<p class="muted" style="font-size:14px">目前没有等待补充的信息。</p>`}${failure&&failure.status==='未完成'?`<div class="object-row"><div class="object-copy"><h3>有一份阅读整理没有完成</h3><p>资料源上次中断，已有内容仍保留。</p>${b('查看并重试','mg-activity:failure')}</div></div>`:''}</section><section aria-labelledby="assistant-upcoming"><div class="section-heading"><h2 id="assistant-upcoming">接下来</h2>${b('计划','nav:plans')}</div>${upcoming.length?upcoming.map(p=>`<button class="object-row" data-action="ex-plan:${plans.indexOf(p)}"><div class="object-copy"><h3>${esc(p.name)}</h3><p>${esc(p.time)} · ${esc(p.on?'演示已开启':'已暂停')}</p></div>${svg('chevron')}</button>`).join(''):'<p class="muted" style="font-size:14px">没有开启的计划，也不必把每件事排进日程。</p>'}${later.length?`<h3 style="margin-top:24px;font-size:14px">你留到稍后看的</h3>${later.map(i=>`<div class="object-row"><div class="object-copy"><h3>${esc(i.title)}</h3><p>只从今日重点移到这里，不会发送提醒。</p>${b('现在看',i.action)}${b('放回今日','as-return:'+i.id)}</div></div>`).join('')}`:''}</section><section aria-labelledby="assistant-kept"><div class="section-heading"><h2 id="assistant-kept">已经替你留下</h2>${b('全部知识点','nav:knowledge')}</div>${complete.length?complete.map(i=>`<button class="object-row" data-action="${i.action}"><div class="object-copy"><h3>${esc(i.title)}</h3><p>${esc(state(i))} · 来源保留，可随时回看</p></div>${svg('chevron')}</button>`).join(''):''}<button class="object-row" data-action="ws-detail:weekend"><div class="object-copy"><h3>周末不用排满，留一点空白</h3><p>聊天里留下的想法，没有被变成待办。</p></div>${svg('chevron')}</button><div class="action-wrap">${b('长期记忆','nav:memory')}${b('资料与结果','nav:data')}</div></section><div class="demo-banner">今日整理是本次个人助理体验的虚构演示，不是实时生成的日报。知识点、Wiki、回忆和长期记忆分别保留；操作只改变本页。</div></section>`}
  function handle(action){if(!action.startsWith('as-'))return false;const [a,id]=action.split(':');const i=items.find(i=>i.id===id);if(!i)return true;if(a==='as-later'){deferred.add(id);render();toast('已移到「接下来」，不会发送真实提醒')}else if(a==='as-return'){deferred.delete(id);render();toast('已放回今日事项')}else if(a==='as-done'){acknowledged.add(id);deferred.delete(id);render();toast('已移到「已经替你留下」')}else if(a==='as-reply'){openDialog('补充一句',`<p class="muted">${esc(i.title)}</p><form id="as-reply-form"><label for="as-reply-text">你想告诉 Nola 的话</label><textarea id="as-reply-text" required placeholder="例如：先保留草案，稍后再一起看看">${esc(notes[id]||'')}</textarea><p class="dialog-note">保存为这件事的演示备注，不会自动执行任何操作。也可以带回来源对话继续聊。</p><div class="dialog-actions">${b('取消','close')}<button class="primary" type="submit">留下这句话</button></div></form>`);dialog.querySelector('form').onsubmit=e=>{e.preventDefault();const t=dialog.querySelector('textarea').value.trim();if(!t)return;notes[id]=t;closeDialog();render();openDialog('已经留好',`<p class="prose">${esc(t)}</p><p class="dialog-note">只是演示备注，还没有发送消息或改变原任务。</p><div class="dialog-actions">${b('先放这里','close')}${b('带回对话继续聊','as-discuss:'+id,'primary')}</div>`)}}else if(a==='as-discuss'){closeDialog();navigate('chat',i.source);drafts[i.source]=(drafts[i.source]||'')+(drafts[i.source]?'\n':'')+(notes[id]||'');render();document.querySelector('#compose')?.focus()}return true}
  return {view:p=>p==='workspace'?view():null,handle,snapshot:()=>({today:items.filter(i=>!deferred.has(i.id)&&!resolved(i)).map(i=>i.id),deferred:[...deferred],acknowledged:[...acknowledged],notes:{...notes}})};
})();
